    apexes = []
    for r, c in markers:
        valid = True
        extent = 0
        for d in range(1, max(h, w)):
            for rr in (r-d, r+d):
                if not 0 <= rr < h:
                    continue
                extent += 1
                for cc in (c-d, c+d):
                    if 0 <= cc < w and (rr, cc) not in markers:
                        valid = False
                        break
                if not valid:
                    break
            if not valid:
                break
        if valid and extent:
            apexes.append((r, c))
    for r, c in apexes:
        for rr in range(h):
            d = abs(rr-r)
            if d == 0:
                continue
            lo, hi = max(0, c-d), min(w-1, c+d)
            if lo <= hi:
                for cc in range(lo, hi+1):
                    if out[rr][cc] == 0:
                        out[rr][cc] = 2
    return out
'''
